func:
// Runs on a clock. Takes the oldest job that the lake watcher queued in
// global context "jobQueue" and sends it to node 1.1 like the inject does.
// One job per tick, so queued jobs run one after another.
var queue = glob.get('jobQueue') || [];
if (!queue.length) {
  return null;
}

var job = queue.shift();
glob.set('jobQueue', queue);
node.status({
  fill: 'green',
  shape: 'dot',
  text: queue.length + ' more queued'
});
return {
  topic: 'listener job',
  payload: job
};

// TASK SETTINGS of the PBI report build: folders, sites, months, dry run.
// In: msg.payload = the job {tables, sites, from, to}; all optional (months
// YYYY-MM, default last month and this month). Out: msg.job, settings stored.

// The source this flow builds. A line whose source (1.1 CONFIG: line
// reportSource, else site reportSource) is this one writes to <root>/report,
// any other to <root>/candidate/<source>.
var SOURCE = 'provideam';
// Folders below the root folder of 1.1 CONFIG, without a leading slash.
var IN_REFERENCE = 'reference';
var IN_SOURCE = 'pbi_report/source';
var OUT_LIVE = 'report';
var OUT_CANDIDATE = 'candidate/' + SOURCE;
var DRY_RUN = {
  Plan_OPT_EU: true,
  Time_Utilisation_EU: true,
  Daily_Losses_EU: true
};

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}
// The sites of 1.1 CONFIG.
var ALL_SITES = shared.sites.map(function (site) {
  return site.name;
});

function fail(text) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: text
  });
  node.error(text);
  return null;
}

// Months from the first to the last one, both as YYYY-MM.
function monthList(from, to) {
  var out = [];
  var year = Number(from.slice(0, 4));
  var month = Number(from.slice(5, 7));
  var last = Number(to.slice(0, 4)) * 12 + Number(to.slice(5, 7));
  while (year * 12 + month <= last) {
    out.push(year + '-' + (month < 10 ? '0' + month : month));
    month++;
    if (month > 12) {
      month = 1;
      year++;
    }
  }
  return out;
}

var asked = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
var allTables = Object.keys(DRY_RUN);
var tables = Array.isArray(asked.tables) ? asked.tables : allTables;
var sites = Array.isArray(asked.sites) ? asked.sites : ALL_SITES;
var unknown = tables.filter(function (t) {
  return allTables.indexOf(t) === -1;
}).concat(sites.filter(function (s) {
  return ALL_SITES.indexOf(s) === -1;
}));
if (unknown.length) {
  return fail('unknown table or site in the job: ' + unknown.join(', '));
}

var now = new Date();
var thisMonth = now.toISOString().slice(0, 7);
var lastMonth = new Date(
  Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)
);
var from = asked.from || lastMonth.toISOString().slice(0, 7);
var to = asked.to || thisMonth;
if (!/^\d{4}-\d{2}$/.test(from) || !/^\d{4}-\d{2}$/.test(to) || from > to) {
  return fail('from and to must be months YYYY-MM, from not after to');
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.referenceFolder = shared.root + '/' + IN_REFERENCE;
cfg.sourceFolder = shared.root + '/' + IN_SOURCE;
cfg.source = SOURCE;
cfg.liveFolder = shared.root + '/' + OUT_LIVE;
cfg.candidateFolder = shared.root + '/' + OUT_CANDIDATE;
flow.set('cfg', cfg);

msg.job = {
  tables: tables,
  sites: sites,
  months: monthList(from, to)
};
var writing = tables.filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts the jobs of the run. In: msg.job {tables, sites, months}.
// Out: the site setup (Glidepaths, Machine Names, Shift Patterns), then the
// month tables of the job, for the sites of the job.
var job = msg.job;

node.status({
  fill: 'green',
  shape: 'dot',
  text: job.tables.length + ' table(s), ' + job.sites.length + ' site(s)'
});
return {
  payload: job.sites,
  job: job,
  day: new Date().toISOString().slice(0, 10),
  mode: 'report',
  loadedAt: Date.now()
};

// Sets the Glidepaths folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'glidepaths';
msg.path = cfg.referenceFolder + '/glidepaths/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the target lookup of one site from its Glidepaths file.
// In: msg.payload = parsed rows (Site Name, Line, OEE Bucket, month columns).
// Stores flow context targets_<site>: machine-site -> month 01/MM/YYYY ->
// {oee, pdt, updt, b: {bucket: value}}. Out 2: a failed item for an empty file.
var BUCKETS = {
  '% OEE': 'oee',
  'Planned Downtime (Total)': 'pdt',
  'Unplanned Downtime (Total)': 'updt'
};
// The file starts with a byte order mark: it sits in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/\uFEFF/g, '')] = row[column];
  });
  return out;
}

var rows = Array.isArray(msg.payload) ? msg.payload.map(clean) : [];
if (!rows.length || rows[0].Line === undefined) {
  msg.payload = {
    failed: 'glidepaths ' + msg.site + ': no Line column or rows'
  };
  return [null, msg];
}

var lookup = {};
var cells = 0;
rows.forEach(function (row) {
  if (!row.Line || !row['Site Name'] || !row['OEE Bucket']) {
    return;
  }
  var field = BUCKETS[row['OEE Bucket']];
  var key = row.Line + '-' + row['Site Name'];
  Object.keys(row).forEach(function (column) {
    var value = String(row[column]).trim();
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(column) || value === '') {
      return;
    }
    var number = Number(value);
    if (isNaN(number)) {
      return;
    }
    lookup[key] = lookup[key] || {};
    lookup[key][column] = lookup[key][column] || {};
    lookup[key][column].b = lookup[key][column].b || {};
    lookup[key][column].b[row['OEE Bucket']] = number;
    if (field) {
      lookup[key][column][field] = number;
    }
    cells++;
  });
});
flow.set('targets_' + msg.site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + cells + ' target values'
});
msg.payload = msg.site;
return [msg, null];

// Sets the folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Machine lookup of one site from its Machine Names file. In: msg.payload =
// parsed rows; stores flow context machines_<Site>: MachineName -> Dept,
// Area, Product Type. Out 2: a failed item. Report filters per site, skipped
// with msg.allMachines (SIH flow: its Config lines choose the machines).
var RULES = {
  Hull: {
    dropNames: [
      'GT4 - Auto'
    ],
    keepDepts: [
      'Dries Pack',
      'Liquids Pack'
    ]
  },
  Nottingham: {
    keepAreas: [
      'SD Packing',
      'Strepsils Packing'
    ]
  },
  Weinheim: {},
  Mira: {}
};

var site = msg.site;
var rule = msg.allMachines ? {} : RULES[site] || {};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  msg.payload = {
    failed: 'machine names ' + site + ': no MachineName column or rows'
  };
  return [null, msg];
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function allowed(list, value) {
  return !list || list.indexOf(value) !== -1;
}

// A machine left out by the rules has no entry: its rows get empty Dept,
// Area and Product Type, as in the report.
var lookup = {};
var kept = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  var dept = text(row.Dept);
  var area = text(row.Area);
  var drop = !name ||
    (rule.dropNames && rule.dropNames.indexOf(name) !== -1) ||
    !allowed(rule.keepDepts, dept) ||
    !allowed(rule.keepAreas, area);
  if (drop) {
    return;
  }
  lookup[name] = {
    'Dept': dept,
    'Area': area,
    'Product Type': text(row['Product Type'])
  };
  kept++;
});
flow.set('machines_' + site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: site + ': ' + kept + ' machines'
});
msg.payload = site;
return [msg, null];

// Sets the folder of the Shift Patterns file for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// eu_report/reference/shift_naming/site=All/, the file of all sites.
var cfg = flow.get('cfg');

msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/shift_naming/site=All/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the shift lookup from the Shift Patterns file.
// In: msg.payload = parsed rows (ShiftName, Shift). Stores flow context
// shiftMap: raw shift name -> Shift. Out 2: a failed item for an empty file.
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (rows.length && rows[0].ShiftName === undefined) {
  // a byte order mark can sit in the first column name
  rows = rows.map(function (row) {
    return {
      ShiftName: row['\uFEFFShiftName'],
      Shift: row.Shift
    };
  });
}
if (!rows.length || rows[0].ShiftName === undefined) {
  msg.payload = {
    failed: 'shift patterns: no ShiftName column or rows'
  };
  return [null, msg];
}

var map = {};
rows.forEach(function (row) {
  if (row.ShiftName !== undefined) {
    map[row.ShiftName] = row.Shift === undefined ? null : row.Shift;
  }
});
flow.set('shiftMap', map);
node.status({
  fill: 'green',
  shape: 'dot',
  text: Object.keys(map).length + ' raw shift names'
});
msg.payload = msg.site;
return [msg, null];

// Sends a site on after its Glidepaths and shift lookups are stored.
// In: the site message, msg.job.tables. Out 1: plan OPT and time utilisation
// months. Out 2: daily losses (equipment lookup, then the months).
var tables = msg.job.tables;
var wantsPlan = tables.indexOf('Plan_OPT_EU') !== -1 ||
  tables.indexOf('Time_Utilisation_EU') !== -1;
var wantsLosses = tables.indexOf('Daily_Losses_EU') !== -1;

node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + (wantsPlan ? 'plan ' : '') +
    (wantsLosses ? 'losses' : '')
});
return [
  wantsPlan ? msg : null,
  wantsLosses ? msg : null
];

// Sets the plan OPT folder of the site for the list objects node.
// In: the message of one site. Out: msg.what and msg.path = the month files
// folder eu_report/pbi_report/source/plan_opt/site=<Site>/.
var cfg = flow.get('cfg');

msg.what = 'plan opt';
msg.filePrefix = 'plan_opt';
msg.path = cfg.sourceFolder + '/plan_opt/site=' + msg.site + '/';
return msg;

// Chooses the month files to build: the months of the job that exist.
// In: msg.payload = objects of a folder, msg.filePrefix, msg.job.months.
// Out 1: msg.payload = list of {month, key} (a split follows). Out 2: a log
// line for months without a file. A missing file would stop a read node.
var items = Array.isArray(msg.payload) ? msg.payload : [];
var found = [];
var missing = [];
msg.job.months.forEach(function (month) {
  var wanted = msg.filePrefix + '_' + month + '.csv';
  var item = items.filter(function (entry) {
    return String(entry.key).slice(-wanted.length) === wanted;
  })[0];
  if (item) {
    found.push({
      month: month,
      key: item.key
    });
  } else {
    missing.push(month);
  }
});

var line = null;
if (missing.length) {
  line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + msg.site +
      ': no ' + msg.filePrefix + ' file for ' + missing.join(', ') + ', skipped'
  };
}
node.status({
  fill: found.length ? 'green' : 'yellow',
  shape: 'dot',
  text: msg.site + ': ' + found.length + ' month(s), ' + missing.length +
    ' missing'
});
if (!found.length) {
  return [null, line];
}
msg.payload = found;
return [msg, line];

// Sets the month file for the read node.
// In: msg.payload = {month, key} (one month after the split). Out: msg.month
// and msg.path = the file, without a tenant folder or a leading slash.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;

msg.month = msg.payload.month;
msg.path = String(msg.payload.key).replace(TENANT_PREFIX, '');
delete msg.payload;
return msg;

// Builds the plan OPT and time utilisation rows of one site and month with
// the rules of the report queries. In: msg.payload = parsed month file, flow
// context shiftMap and targets_<site>. Out 1: plan table, out 2: time
// utilisation table (for the decide nodes), out 3: a check log line.
var HULL_SKIP = [
  'GT4 - Auto',
  '4 Tonne',
  '6 Tonne',
  '6000L',
  'Analgesics Processing',
  'Analgesics X Press',
  'Bosch Capsulator ',
  'Dettol 1',
  'Evolution',
  'Fitten',
  'Gaviscon TPR',
  'Gaviscon XP700(A)',
  'GG4',
  'GG5',
  'GG6',
  'GG7',
  'Lemsip Process',
  'Senokot Press',
  'Symex suite',
  'Vacumix'
];
var NOTTS_UTIL_KEEP = [
  'N1',
  'N10',
  'N11',
  'N12',
  'N3',
  'N4',
  'N5',
  'N6',
  'N7',
  'N8',
  'N9 Auto',
  'O5',
  'O6',
  'S04',
  'S05',
  'S06',
  'S08',
  'S10',
  'S11',
  'S12',
  'S13',
  'T2',
  'T7'
];
var RULES = {
  Hull: {
    planSkip: HULL_SKIP,
    utilSkip: HULL_SKIP,
    replaceText: [
      ['Gavi 12 X 150 Russian Crypto', 'Gavi 12 x 150 russian Crypto']
    ]
  },
  Nottingham: {
    planAreas: [
      ' Strepsils Packing',
      'SD Packing'
    ],
    planSkip: [
      'N11 Auto',
      'S14'
    ],
    utilKeep: NOTTS_UTIL_KEEP,
    utilSkip: [
      'N11 Auto'
    ]
  },
  Weinheim: {
    planSkip: [
      'N11 Auto'
    ],
    utilSkip: [],
    partCutChars: 8
  }
};
var UTIL_ALL_TIME = 1440;

var site = msg.site;
var rule = RULES[site] || {};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var shiftMap = flow.get('shiftMap') || {};
var targets = flow.get('targets_' + site) || {};
var count = {
  read: rows.length,
  planned: 0,
  planSkipped: 0,
  utilSkipped: 0,
  noShift: {},
  noTarget: {}
};
var planRows = [];
var utilByKey = {};
var utilOrder = [];

function inList(list, value) {
  return !!list && list.indexOf(value) !== -1;
}

// The csv node leaves empty cells out of the row: an empty text is ''.
function asText(value) {
  return value === undefined || value === null ? '' : String(value);
}

// Days since 1970-01-01 of a date text YYYY-MM-DD: the value of a DATE column.
function dayNumber(text) {
  var year = Number(text.slice(0, 4));
  var month = Number(text.slice(5, 7));
  var day = Number(text.slice(8, 10));
  return Date.UTC(year, month - 1, day) / 86400000;
}

function number(value) {
  var text = value === undefined || value === null ? '' : String(value).trim();
  return text === '' || isNaN(Number(text)) ? null : Number(text);
}

// "H:MM:SS" (hours can pass 24) -> {whole: minutes without seconds, exact}.
function minutes(value) {
  var parts = /^(\d+):(\d{2}):(\d{2})$/.exec(String(value).trim());
  if (!parts) {
    return null;
  }
  var base = Number(parts[1]) * 60 + Number(parts[2]);
  return {
    whole: base,
    exact: base + Number(parts[3]) / 60
  };
}

// Part name of the site: text replaced, or the first characters cut off (the
// Weinheim part code and its space, as the report does). Trailing spaces go:
// the report data has none (leading spaces stay).
function replaceText(text) {
  var out = rule.partCutChars ? text.slice(rule.partCutChars) : text;
  out = out.replace(/\s+$/, '');
  (rule.replaceText || []).forEach(function (pair) {
    out = out.split(pair[0]).join(pair[1]);
  });
  return out;
}

rows.forEach(function (row) {
  var machine = row.MachineName;
  if (machine === undefined || machine === null || machine === '') {
    return;
  }
  var date = row['YYYY-MM-DD'];
  var total = minutes(row['Total Time']);
  var planned = minutes(row['Planned OpT']);
  var used = minutes(row['OEE Time']);
  var unique = machine + '-' + site;

  // Time utilisation: its own machine rules, sums per machine and day.
  if (inList(rule.utilSkip, machine) ||
      (rule.utilKeep && !inList(rule.utilKeep, machine))) {
    count.utilSkipped++;
  } else {
    var key = date + '|' + machine;
    if (!utilByKey[key]) {
      utilByKey[key] = {
        'Date': dayNumber(date),
        'MachineName': machine,
        'OEE Time Total': 0,
        'Total Time Total': 0,
        'Planned OPT Total': 0,
        'SiteName': site,
        'Unique Machine Name': unique,
        'All Time': UTIL_ALL_TIME,
        'loaded_at': msg.loadedAt
      };
      utilOrder.push(key);
    }
    utilByKey[key]['Total Time Total'] += total ? total.exact : 0;
    utilByKey[key]['Planned OPT Total'] += planned ? planned.exact : 0;
    utilByKey[key]['OEE Time Total'] += used ? used.exact : 0;
  }

  // Plan OPT: the machine and area rules of the site.
  if (inList(rule.planSkip, machine) ||
      (rule.planAreas && !inList(rule.planAreas, row.AreaName))) {
    count.planSkipped++;
    return;
  }
  var part = replaceText(asText(row.PartName));
  var known = shiftMap.hasOwnProperty(row.ShiftName);
  var shift = known ? shiftMap[row.ShiftName] : null;
  if (shift === null) {
    count.noShift[row.ShiftName] = true;
  }
  var monthText = '01/' + date.slice(5, 7) + '/' + date.slice(0, 4);
  var target = (targets[unique] || {})[monthText] || {};
  if (target.oee === undefined) {
    count.noTarget[unique] = true;
  }
  count.planned++;
  planRows.push({
    'Date': dayNumber(date),
    'AreaName': asText(row.AreaName),
    'MachineName': machine,
    'ShiftName': shift,
    'PartName': part,
    'Good Parts': number(row['Good Parts']),
    'Capacity': number(row.Capacity),
    'Total Time': total ? total.whole : null,
    'Planned OpT': planned ? planned.whole : null,
    'OEE Time': used ? used.whole : null,
    'Downtime Units': number(row['Downtime Units']),
    'SiteName': site,
    'Unique Machine Name': unique,
    'Product Key': unique + ' ' + part,
    'UPDT Target': target.updt === undefined ? null : target.updt,
    'PDT Target': target.pdt === undefined ? null : target.pdt,
    'OEE Target': target.oee === undefined ? null : target.oee,
    'source_hours': null,
    'loaded_at': msg.loadedAt
  });
});

function tableMsg(table, tableRows) {
  return {
    table: table,
    rows: tableRows,
    failed: [],
    skipped: [],
    itemCount: 1,
    site: site,
    month: msg.month,
    day: msg.day,
    mode: msg.mode,
