// Builds the volume loss correction lookup of one site and month.
// In: msg.payload = parsed month file. Stores flow context vc_<site>_<month>:
// key (date machine group subgroup description, as the report builds it) ->
// {u: loss units rounded to a whole number, m: time in minutes with seconds}.
var BREAKDOWN = [
  ['Breakdown - Mechanical', 'Breakdown'],
  ['Breakdown - Electrical', 'Breakdown']
];
// Text replacements of the report queries of each site, in their order.
var RULES = {
  Hull: {
    sub: BREAKDOWN.concat([
      ['In Process Quality Control', 'In process Quality Control'],
      ['Lack of resources', 'Lack of Resource']
    ]),
    group: []
  },
  Nottingham: {
    sub: BREAKDOWN.concat([
      ['Lack of resources', 'Lack of Resource']
    ]),
    group: [
      ['Planned Losses', 'Planned Loss'],
      ['Unplanned Losses', 'Unplanned Loss']
    ]
  },
  Weinheim: {
    sub: [],
    group: []
  }
};
var rule = RULES[msg.site] || {
  sub: [],
  group: []
};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var map = {};
var count = 0;

function replaceAll(text, pairs) {
  var out = text;
  pairs.forEach(function (pair) {
    out = out.split(pair[0]).join(pair[1]);
  });
  return out;
}

// The csv node leaves empty cells out of the row: an empty text is ''.
function asText(value) {
  return value === undefined || value === null ? '' : String(value);
}

function minutes(value) {
  var parts = /^(\d+):(\d{2}):(\d{2})$/.exec(String(value).trim());
  if (!parts) {
    return null;
  }
  return Number(parts[1]) * 60 + Number(parts[2]) + Number(parts[3]) / 60;
}

rows.forEach(function (row) {
  var machine = asText(row.MachineName);
  var day = asText(row.ShiftStartDate);
  if (!machine || !day) {
    return;
  }
  var dayText = day.slice(8, 10) + '/' + day.slice(5, 7) + '/' +
    day.slice(0, 4);
  var key = dayText + ' ' + machine + ' ' +
    replaceAll(asText(row.OEELossLvl3Group), rule.group) + ' ' +
    replaceAll(asText(row.OEELossLvl3SubGroup), rule.sub) + ' ' +
    asText(row.OEELossLvl3Desc);
  var units = asText(row['Loss Units']).trim() === '' ? NaN :
    Number(asText(row['Loss Units']).trim());
  // Two correction rows can get the same key after the text replacements
  // (Breakdown - Electrical and - Mechanical): the first one is kept, as the
  // report does (checked against its Daily Losses table, 2026-10-17).
  if (map[key] !== undefined) {
    return;
  }
  map[key] = {
    u: isNaN(units) ? null : Math.round(units),
    m: minutes(row.Time)
  };
  count++;
});
flow.set('vc_' + msg.site + '_' + msg.month, map);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ' ' + msg.month + ': ' + count + ' correction rows'
});
delete msg.payload;
return msg;

// Sets the month file of one type for the read node, or skips it.
// In: msg.site, msg.month (flow context have_<type>_<site>). Out 1: msg.path.
// Out 2: the file does not exist and the type is optional: an empty lookup is
// stored (flow context <KEY>_<site>_<month>) and the month goes on.
var TYPE = 'plan_opt';
var KEY = 'cap';
var OPTIONAL = true;
var cfg = flow.get('cfg');
var have = flow.get('have_' + TYPE + '_' + msg.site) || [];

if (have.indexOf(msg.month) === -1 && OPTIONAL) {
  flow.set(KEY + '_' + msg.site + '_' + msg.month, {});
  node.status({
    fill: 'yellow',
    shape: 'ring',
    text: msg.site + ' ' + msg.month + ': no ' + TYPE + ' file'
  });
  return [null, msg];
}
msg.path = cfg.sourceFolder + '/' + TYPE + '/site=' + msg.site + '/';
msg.path += TYPE + '_' + msg.month + '.csv';
return [msg, null];

// Builds the volume total lookup of one site and month (Targets Volume).
// In: msg.payload = parsed plan OPT month file. Stores flow context
// cap_<site>_<month>: "machine dd/MM/yyyy" -> sum of Capacity of that day.
// Machines left out as in the report: blank, GT4 - Auto (Hull), N11 Auto.
var SKIP = {
  Hull: ['GT4 - Auto'],
  Nottingham: ['N11 Auto'],
  Weinheim: ['N11 Auto']
};
var skip = SKIP[msg.site] || [];
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var map = {};
var days = 0;

rows.forEach(function (row) {
  var machine = row.MachineName;
  var day = row['YYYY-MM-DD'];
  if (!machine || !day || skip.indexOf(machine) !== -1) {
    return;
  }
  var text = day.slice(8, 10) + '/' + day.slice(5, 7) + '/' + day.slice(0, 4);
  var key = machine + ' ' + text;
  var capacity = Number(String(row.Capacity).trim());
  if (map[key] === undefined) {
    map[key] = 0;
    days++;
  }
  map[key] += isNaN(capacity) ? 0 : capacity;
});
flow.set('cap_' + msg.site + '_' + msg.month, map);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ' ' + msg.month + ': ' + days + ' machine-days'
});
delete msg.payload;
return msg;

// Sets the line loss month file for the read node.
// In: msg.site, msg.month (the month exists: it was chosen from the list).
// Out: msg.path = <source>/line_losses/site=<Site>/line_losses_<YYYY-MM>.csv.
var cfg = flow.get('cfg');

msg.path = cfg.sourceFolder + '/line_losses/site=' + msg.site + '/';
msg.path += 'line_losses_' + msg.month + '.csv';
return msg;

// Builds the Daily_Losses_EU rows of one site and month with the steps of
// the report queries (Daily Line Losses H, N, W and Daily Losses Provideam).
// In: msg.payload = parsed line loss file; flow context vc_, cap_, equip_,
// targets_, shiftMap. Out 1: the table message, out 2: a check log line.
var HULL_SKIP = [
  '4 Tonne',
  '6 Tonne',
  '6000L',
  'Analgesics Processing',
  'Analgesics X Press',
  'Bosch Capsulator ',
  'Dettol 1',
  'Evolution',
  'Fitten',
  'Gaviscon TPR',
  'Gaviscon XP700(A)',
  'GG4',
  'GG5',
  'GG6',
  'GG7',
  'Lemsip Process',
  'Senokot Press',
  'Symex suite',
  'Vacumix'
];
var NOTTS_SKIP = [
  'Bosch',
  'Fette 23',
  'Fette12',
  'Fette2',
  'Fette20',
  'Fette4',
  'Fette5',
  'Gran0',
  'S14'
];
var EARLY_SKIP = [
  'B1 - Auto',
  'B4 Auto',
  'B5 Auto'
];
var GROUPS = [
  'Not Logged',
  'Planned Loss',
  'Unplanned Loss'
];
var BREAKDOWN = [
  ['Breakdown - Mechanical', 'Breakdown'],
  ['Breakdown - Electrical', 'Breakdown']
];
var HULL_FINAL = [
  ['Adjustment', 'Adjustments'],
  ['Start-Up/End-Up & Sanitization', 'Start up and Sanitisation'],
  ['In Process Quality Control', 'In Process Quality'],
  ['Lack Of Resource', 'Lack Of Resources'],
  ['Meals & Breaks', 'Breaks / Meals'],
  ['Minor Stop', 'Minor Stops'],
  ['Other', 'Others'],
  ['Product Change Over', 'Product Changeover'],
  ['Start Up And Sanitisation', 'Start up and Sanitisation'],
  ['Lack Of Resourcess', 'Lack Of Resources'],
  ['Operater Asset Care', 'Operator Asset Care'],
  ['Beakdown - Mechanical', 'Breakdown']
];
// Steps of each site, in the order of its query: text replacements before
// the volume key (keyReplace, groupBefore), after the correction join
// (afterJoin), Text.Proper (proper), the final subgroup list (final).
var RULES = {
  Hull: {
    breakdownTypes: true,
    earlyFilter: true,
    keyReplace: BREAKDOWN,
    groupBefore: [],
    afterJoin: [
      ['Adjustments', 'Adjustment'],
      ['Breaks and Meal', 'Meals & Breaks'],
      ['Lack of resources', 'Lack of Resource']
    ],
    groups: GROUPS,
    groupAfter: [],
    proper: true,
    final: HULL_FINAL,
    skip: HULL_SKIP
  },
  Nottingham: {
    breakdownTypes: true,
    earlyFilter: true,
    keyReplace: BREAKDOWN,
    groupBefore: [
      ['Planned Losses', 'Planned Loss'],
      ['Unplanned Losses', 'Unplanned Loss']
    ],
    afterJoin: [
      ['Breaks and Meal', 'Meals & Breaks'],
      ['Lack of resources', 'Lack of Resource']
    ],
    groups: GROUPS,
    groupAfter: [],
    proper: false,
    final: [
      ['Minor Stop', 'Minor Stops'],
      ['Lack of Resources', 'Lack Of Resources'],
      ['Other', 'Others'],
      ['Meals & Breakss', 'Breaks / Meals'],
      ['In Process Quality Control', 'In Process Quality'],
      ['Start up & Sanitisation', 'Start up and Sanitisation']
    ],
    skip: NOTTS_SKIP
  },
  Weinheim: {
    breakdownTypes: false,
    earlyFilter: false,
    cutPart: 8,
    keyReplace: [],
    groupBefore: [],
    afterJoin: [],
    groups: null,
    groupAfter: [
      ['Planned Losses', 'Planned Loss'],
      ['Unplanned losses', 'Unplanned Loss']
    ],
    proper: true,
    final: [
      ['Adjustment', 'Adjustments'],
      ['Breakdowns', 'Breakdown'],
      ['Coding', 'Breakdown'],
      ['Meals&Breaks', 'Breaks / Meals'],
      ['Other', 'Others'],
      ['Start-Upend-Up Sanitization', 'Start up and Sanitisation'],
      ['Changeover', 'Product Changeover'],
      ['In Process Control', 'In Process Quality'],
      ['Rework', 'In Process Quality']
    ],
    skip: []
  }
};

var site = msg.site;
var rule = RULES[site] || RULES.Weinheim;
var rows = Array.isArray(msg.payload) ? msg.payload : [];
var vcMap = flow.get('vc_' + site + '_' + msg.month) || {};
var capMap = flow.get('cap_' + site + '_' + msg.month) || {};
var equipMap = flow.get('equip_' + site) || {};
var targets = flow.get('targets_' + site) || {};
var shiftMap = flow.get('shiftMap') || {};
var seen = {};
var out = [];
var count = {
  read: rows.length,
  dupes: 0,
  early: 0,
  group: 0,
  last: 0,
  noUnits: 0,
  noEquip: 0,
  noTarget: 0,
  noShift: {}
};

function replaceAll(text, pairs) {
  var result = text;
  pairs.forEach(function (pair) {
    result = result.split(pair[0]).join(pair[1]);
  });
  return result;
}

// Text.Proper: the first letter of every word capital, the rest small.
function proper(text) {
  var result = '';
  for (var i = 0; i < text.length; i++) {
    var letter = text.charAt(i);
    var before = i ? text.charAt(i - 1) : ' ';
    var after = before.toLowerCase() === before.toUpperCase();
    result += after ? letter.toUpperCase() : letter.toLowerCase();
  }
  return result;
}

// The csv node leaves empty cells out of the row: an empty text is ''.
function asText(value) {
  return value === undefined || value === null ? '' : String(value);
}

function minutes(value) {
  var parts = /^(\d+):(\d{2}):(\d{2})$/.exec(String(value).trim());
  return parts ? Number(parts[1]) * 60 + Number(parts[2]) : null;
}

// "H:MM:SS" (hours can pass 24) -> seconds, with the seconds of the file.
function seconds(value) {
  var parts = /^(\d+):(\d{2}):(\d{2})$/.exec(String(value).trim());
  if (!parts) {
    return null;
  }
  return Number(parts[1]) * 3600 + Number(parts[2]) * 60 + Number(parts[3]);
}

// Days since 1970-01-01 of a date text YYYY-MM-DD (a DATE column value).
function dayNumber(text) {
  var parts = /^(\d{4})-(\d{2})-(\d{2})/.exec(text);
  if (!parts) {
    return null;
  }
  return Date.UTC(Number(parts[1]), Number(parts[2]) - 1, Number(parts[3])) /
    86400000;
}

// Milliseconds of the day of a time text HH:MM:SS (the parquet node cannot
// write the Excel day 1899-12-30, so a time of day is on 1970-01-01).
function timeOfDay(text) {
  var secs = seconds(text);
  return secs === null ? null : secs * 1000;
}

// The target as text with a decimal point, like the report (15.0, 3.9).
function valueText(number) {
  if (number === null) {
    return null;
  }
  return Number.isInteger(number) ? number + '.0' : String(number);
}

function dayText(day) {
  return day.slice(8, 10) + '/' + day.slice(5, 7) + '/' + day.slice(0, 4);
}

rows.forEach(function (row) {
  var machine = row.MachineName;
  if (machine === undefined || machine === null || machine === '') {
    return;
  }
  var start = asText(row.StartTime);
  var mergedKey = machine + ' ' + start;
  if (seen[mergedKey]) {
    count.dupes++;
    return;
  }
  seen[mergedKey] = true;
  var group = asText(row.OEELossLvl3Group);
  var sub = asText(row.OEELossLvl3SubGroup);
  var desc = asText(row.OEELossLvl3Desc);
  var breakdownTypes = rule.breakdownTypes ? sub : null;
  sub = replaceAll(sub, rule.keyReplace);
  group = replaceAll(group, rule.groupBefore);
  if (rule.earlyFilter &&
      (group === '' || group === '0.Review Data' ||
        EARLY_SKIP.indexOf(machine) !== -1)) {
    count.early++;
    return;
  }
  var day = asText(row.ShiftStartDate);
  var daily = dayText(day);
  var volumeKey = daily + ' ' + machine + ' ' + group + ' ' + sub + ' ' + desc;
  var correction = vcMap[volumeKey];
  sub = replaceAll(sub, rule.afterJoin);
  var equipment = equipMap[machine + ' ' + desc] || [null];
  if (rule.groups && rule.groups.indexOf(group) === -1) {
    count.group++;
    return;
  }
  group = replaceAll(group, rule.groupAfter);
  sub = rule.proper ? proper(sub) : sub;
  sub = replaceAll(sub, rule.final);
  if (rule.skip.indexOf(machine) !== -1) {
    count.last++;
    return;
  }
  var unique = machine + '-' + site;
  var part = rule.cutPart ? asText(row.PartName).slice(rule.cutPart) :
    asText(row.PartName);
  // Trailing spaces go: the report data has none (as in the plan OPT rows).
  part = part.replace(/\s+$/, '');
  var shift = shiftMap.hasOwnProperty(row.ShiftName) ?
    shiftMap[row.ShiftName] : null;
  if (shift === null) {
    count.noShift[row.ShiftName] = true;
  }
  var monthText = '01/' + day.slice(5, 7) + '/' + day.slice(0, 4);
  var target = (targets[unique] || {})[monthText];
  var value = target && target.b && target.b[sub] !== undefined ?
    target.b[sub] : null;
  if (value === null) {
    count.noTarget++;
  }
  var duration = minutes(row.Duration);
  var durationSeconds = seconds(row.Duration);
  var units = null;
  if (correction && correction.u !== null && correction.m &&
      duration !== null) {
    units = correction.u * duration / correction.m;
  } else {
    count.noUnits++;
  }
  var capacity = capMap[machine + ' ' + daily];
  equipment.forEach(function (name) {
    if (name === null) {
      count.noEquip++;
    }
    out.push({
      'Date': dayNumber(start.slice(0, 10)),
      'Time': timeOfDay(start.slice(11, 19)),
      'MachineName': machine,
      'PartName': part,
      'Shift Time': shift,
      'ShiftName': shift,
      'OEELossLvl3Group': group,
      'OEELossLvl3SubGroup': sub,
      'OEELossLvl3Desc': desc,
      'Duration': durationSeconds === null ? null : durationSeconds * 1000,
      'SiteName': site,
      'Unique Machine Name': unique,
      'Breakdown Types': breakdownTypes,
      'ShiftStartDate': dayNumber(day),
      'Comment': asText(row.Comment) === '' ? null : asText(row.Comment),
      'Product Key': unique + ' ' + part,
      'Volume Key': volumeKey,
      'Loss Units': units,
      'Time in Mins': durationSeconds === null ? null : durationSeconds / 60,
      'Equipment Loss Key': machine + ' ' + desc,
      'Equipment': name,
      'Lvl 3 Loss Name': desc,
      'Loss Target Key': unique + ' ' + sub + ' ' + monthText,
      'Value': valueText(value),
      'Volume Total': capacity === undefined ? null : capacity,
      'Loss Final Level': desc,
      'target': value === null ? null : value / 100,
      'batch_id': null,
      'comment_count': null,
      'loaded_at': msg.loadedAt
    });
  });
});
flow.set('vc_' + site + '_' + msg.month, undefined);
flow.set('cap_' + site + '_' + msg.month, undefined);

var text = site + ' ' + msg.month + ': read ' + count.read + ' rows, kept ' +
  out.length + ' (duplicate starts ' + count.dupes + ', early filter ' +
  count.early + ', group filter ' + count.group + ', machine list ' +
  count.last + '), no loss units ' + count.noUnits + ', no equipment ' +
  count.noEquip + ', no target ' + count.noTarget;
var noShift = Object.keys(count.noShift);
if (noShift.length) {
  text += ', shift not mapped: ' + noShift.slice(0, 5).join(' / ');
}
node.status({
  fill: out.length ? 'green' : 'yellow',
  shape: 'dot',
  text: site + ' ' + msg.month + ': ' + out.length + ' rows'
});
return [
  {
    table: 'Daily_Losses_EU',
    rows: out,
    failed: [],
    skipped: [],
    itemCount: 1,
    site: site,
    month: msg.month,
    day: msg.day,
    mode: msg.mode,
    loadedAt: msg.loadedAt,
    job: msg.job
  },
  {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] CHECK ' + text
  }
];

// Adds the machine columns and the source to the rows of one table month.
// In: msg.rows of one site and month. Out: the same rows with Dept, Area,
// Product Type (flow context machines_<Site>) and Data Source.
var DATA_SOURCE = 'Provideam';
var machines = flow.get('machines_' + msg.site) || {};

var unknown = {};
msg.rows.forEach(function (row) {
  var machine = machines[row.MachineName];
  if (!machine) {
    unknown[row.MachineName] = true;
  }
  row['Dept'] = machine ? machine['Dept'] : null;
  row['Area'] = machine ? machine['Area'] : null;
  row['Product Type'] = machine ? machine['Product Type'] : null;
  row['Data Source'] = DATA_SOURCE;
});
var missing = Object.keys(unknown);
if (missing.length) {
  var text = 'not in Machine Names (no Dept, Area, Product Type): ';
  text += missing.slice(0, 5).join(' / ');
  msg.skipped.push(text);
}
return msg;

// Splits the rows of one table month by the source of their line (1.1
// CONFIG: line reportSource, else site reportSource). In: msg.rows. Out: one
// message per folder (msg.out = report or candidate/<source>) with its rows.
var cfg = flow.get('cfg');
var site = cfg.sites.filter(function (entry) {
  return entry.name === msg.site;
})[0];

// MachineName of a Config line -> the source of that line.
var lineSource = {};
(site.lines || []).forEach(function (line) {
  lineSource[line.report] = line.reportSource || site.reportSource;
});

var live = [];
var candidate = [];
var moved = {};
msg.rows.forEach(function (row) {
  var source = lineSource[row.MachineName] || site.reportSource;
  if (source === cfg.source) {
    live.push(row);
    return;
  }
  candidate.push(row);
  moved[row.MachineName] = true;
});

function part(out, rows) {
  var copy = Object.assign({}, msg);
  copy.out = out;
  copy.rows = rows;
  copy.skipped = msg.skipped.slice();
  return copy;
}

var out = [];
if (live.length || !candidate.length) {
  out.push(part(cfg.liveFolder, live));
}
if (candidate.length) {
  var note = 'to ' + cfg.candidateFolder + ': ';
  note += Object.keys(moved).join(' / ');
  // shortcut: an old report file of the month is not deleted when all its
  // rows move to candidate; delete it by hand when a whole site switches.
  if (!live.length) {
    note += ' (no rows left for report/: its old file of the month stays)';
  }
  var moving = part(cfg.candidateFolder, candidate);
  moving.skipped.push(note);
  out.push(moving);
}
return [out];

// Decides what happens with the table Daily_Losses_EU.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'Daily_Losses_EU';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';
if (msg.out) {
  sizes += ' to ' + msg.out;
}

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path of one month: <out>/<table>/site=<Site>/<table>_
// <YYYY-MM>_<source>.parquet, <out> = report or candidate/<source>.
// In: the parquet node output (msg.out, table, site, month). Out: msg.path.
// The name is fixed per source: a rerun replaces only this source's month.
var cfg = flow.get('cfg');

msg.path = msg.out + '/' + msg.table + '/site=' + msg.site;
msg.path += '/' + msg.table + '_' + msg.month + '_' + cfg.source;
msg.path += '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Turns a failed item into a log line. In: msg.payload = {failed: text}
// (a file that was not found or empty). Out: the log line. Nothing is built
// for the site, so no table file is written for it in this run.
var line = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] FAILED, NOTHING WRITTEN: ' +
    msg.payload.failed
};
return line;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'pbi-report';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Notes the time of the newest log line in global context "lastLog".
// In: every log line (a tap behind the log formatter). Out: nothing. A new
// line also clears the "done" flag, so the next quiet period is reported.
glob.set('lastLog', Date.now());
glob.set('done', false);
return null;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'pbi-report';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
